<template><div class="diff-view"><header><strong>Diferença DSM − DTM</strong><div><button title="Fechar" @click="$emit('close')"><i class="pi pi-times"></i></button></div></header><div class="canvas-wrap"><canvas ref="canvas"></canvas><div v-if="loading" class="loading">Calculando diferenças...</div></div><div class="legend"><span>{{ stats.min.toFixed(1) }} m</span><i></i><span>0</span><i class="positive"></i><span>{{ stats.max.toFixed(1) }} m</span><b>Média {{ stats.mean.toFixed(2) }} m</b></div></div></template>
<script setup>
import { ref, onMounted } from 'vue'; import { getElevationDifference } from '../api/client'
const props=defineProps({processingId:{type:Number,required:true}}); defineEmits(['close']); const canvas=ref(null),loading=ref(true),stats=ref({min:0,max:0,mean:0})
onMounted(async()=>{try{const {data}=await getElevationDifference(props.processingId,128);stats.value={min:data.min,max:data.max,mean:data.mean};const c=canvas.value,ctx=c.getContext('2d'),h=data.height,w=data.width;c.width=w;c.height=h;const span=Math.max(Math.abs(data.min),Math.abs(data.max),1);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const v=data.differences[y][x],t=Math.max(-1,Math.min(1,v/span));ctx.fillStyle=t<0?`rgb(${Math.round(40+180*(t+1))},${Math.round(100+100*(t+1))},220)`:`rgb(240,${Math.round(180-120*t)},${Math.round(70-50*t)})`;ctx.fillRect(x,y,1,1)}}catch(e){console.error(e)}finally{loading.value=false}})
</script><style scoped>.diff-view{position:fixed;inset:8vh 12vw;background:#101820;color:#e8f0f2;z-index:2200;display:flex;flex-direction:column;border:1px solid #40515c}.diff-view header{display:flex;justify-content:space-between;padding:12px 16px;background:#17242c}.diff-view button{background:transparent;border:1px solid #52616b;color:#dce7eb;width:34px;height:30px}.canvas-wrap{position:relative;flex:1;display:grid;place-items:center;background:#0b1116}.canvas-wrap canvas{width:min(90%,900px);height:min(75%,650px);image-rendering:pixelated}.loading{position:absolute;inset:0;display:grid;place-items:center;background:#101820cc}.legend{display:flex;align-items:center;gap:8px;padding:10px 16px;background:#17242c;font-size:.72rem}.legend i{width:90px;height:10px;background:linear-gradient(90deg,#2878dc,#b4c8dc,#f04646)}.legend i.positive{display:none}.legend b{margin-left:auto;color:#ffcf56}</style>
